// tg: code/modules/mapfluff/ruins/spaceruin_code/listeningstation.dm:15
[DmPath("/obj/item/paper/fluff/ruins/listeningstation/reports/april"), DmGeneratedOnly]
public partial class obj_item_paper_fluff_ruins_listeningstation_reports_april : obj_item_paper_fluff_ruins_listeningstation_reports
{
    // tg: code/modules/mapfluff/ruins/spaceruin_code/listeningstation.dm:15
