    public obj_item_paper_fluff_ruins_oldstation_damagereport()
    {
        name = "Damage Report";
        default_raw_text = "<h2>WARNING</h2> <ul> <li>Shields down. Space Carp invasion imminent.</li> <li>Unknown force has overtaken AI satellite and occupying Delta Station. Intent unknown. Species unknown. Numbers unknown.</li> </ul> <h2>Status</h2> <ol> <li><b>Alpha Station</b> - Destroyed.</li> <li><b>Beta Station</b> - Catastrophic Damage. Medical, destroyed. Atmospherics and Engine Core, partially destroyed.</li> <li><b>Charlie Station</b> - Multiple asteroid impacts, no loss in air pressure.</li> <li><b>Delta Station</b> - Intact.</li> </ol> <h2>Recommended Actions</h2> <ol> <li>Locate arms at Charlie Station Security.</li> <li>Move at a sufficient distance from the windows to avoid encounters with Space Carp.</li> <li>Reestablish station powernet via Charlie Station Engineering solar array.</li> <li>Restore life support systems: atmospherics, artificial gravity, hydroponics.</li> <li>Avoid Delta Station until arrival of Nanotrasen Special Response Team.</li> </ol>";
    }
}

// tg: code/modules/mapfluff/ruins/spaceruin_code/oldstation/oldstation_fluff.dm:37
[DmPath("/obj/item/paper/fluff/ruins/oldstation/protosuit"), DmGeneratedOnly]
public partial class obj_item_paper_fluff_ruins_oldstation_protosuit : obj_item_paper_fluff_ruins_oldstation
{
    // tg: code/modules/mapfluff/ruins/spaceruin_code/oldstation/oldstation_fluff.dm:37
    public obj_item_paper_fluff_ruins_oldstation_protosuit()
    {
        name = "B01-MOD modular suit Report";
        default_raw_text = "<b>*Prototype MODsuit*</b><br><br>This is a prototype powered exoskeleton, a design not seen in hundreds of years, the first post-void war era modular suit to ever be safely utilized by an operator. This ancient clunker is still functional, though it's missing several modern-day luxuries from updated Nakamura Engineering designs. Primarily, the suit's myoelectric suit layer is entirely non-existant, and the servos do very little to help distribute the weight evenly across the wearer's body, making it slow and bulky to move in. Additionally, the armor plating never finished production aside from the shoulders, forearms, and helmet; making it useless against direct attacks. The internal heads-up display is rendered entirely in monochromatic cyan, leaving the user unable to see long distances. However, the way the helmet retracts is pretty cool.";
    }
}

// tg: code/modules/mapfluff/ruins/spaceruin_code/oldstation/oldstation_fluff.dm:48
