        name = "Health Analyzer Report";
        default_raw_text = "<b>*Health Analyzer*</b><br><br>The portable Health Analyzer is essentially a handheld variant of a health analyzer. Years of research have concluded with this device which is capable of diagnosing even the most critical, obscure or technical injuries any humanoid entity is suffering in an easy to understand format that even a non-trained health professional can understand.<br><br>The health analyzer is expected to go into full production as standard issue medical kit.";
    }
}

// tg: code/modules/mapfluff/ruins/spaceruin_code/oldstation/oldstation_fluff.dm:54
[DmPath("/obj/item/paper/fluff/ruins/oldstation/protogun"), DmGeneratedOnly]
