    public obj_item_paper_fluff_ruins_oldstation_biolab_note_molly()
    {
        name = "Diary note - Molly";
        default_raw_text = "It has been several months since our Molly passed away. She was our most valuable crew member, especially compared to that prick that happily threw a party to make sure `that beef won't go to waste`...<br><br> Oh, how I miss her warm milk...<br><br>I've put Molly's biopsy in the fridge and almost completed the solution.<br><br> Next steps:<ul><li>Pour the broth to the growing vat (beaker nearby)</li><li>Add one dropper of the solution</li><li>Add Molly's biopsy to the vat</li></ul> Just need to make sure to use the correct bottle this time... I'll even mark it as <b>\"Solution for Molly\"</b>, or I tend to mix things up... <br>I can already feel the endorphin release from hugging her again.<br><br> If everything goes well, I will try out those slimes the papers praising as the future of science. They say that the cell lines may be found on anything moldy and rotting, and these small blobs have crazy mutation potential when properly fed.";
    }
}

// tg: code/modules/mapfluff/ruins/spaceruin_code/oldstation/oldstation_fluff.dm:102
