[DmPath("/obj/item/paper/guides/jobs/atmos/hypertorus"), DmGeneratedOnly]
public partial class obj_item_paper_guides_jobs_atmos_hypertorus : obj_item_paper_guides_jobs_atmos
{
    // tg: code/modules/atmospherics/machinery/components/fusion/hfr_parts.dm:389
    public obj_item_paper_guides_jobs_atmos_hypertorus()
    {
        name = "paper- 'Quick guide to safe handling of the HFR'";
        default_raw_text = "<B>How to safely(TM) operate the Hypertorus</B><BR>-Build the machine as it\ufffds shown in the main guide.<BR>-Make a 50/50 gasmix of tritium and hydrogen totalling around 2000 moles.<BR>-Start the machine, fill up the cooling loop with plasma/hypernoblium and use space or freezers to cool it.<BR>-Connect the fuel mix into the fuel injector port, allow only 1000 moles into the machine to ease the kickstart of the reaction<BR>-Set the Heat conductor to 500 when starting the reaction, reset it to 100 when power level is higher than 1<BR>-In the event of a meltdown, set the heat conductor to max and set the current damper to max. Set the fuel injection to min. If the heat output doesn\ufffdt go negative, try changing the magnetic costrictors untill heat output goes negative. Make the cooling stronger, put high heat capacity gases inside the moderator (hypernoblium will help dealing with the problem)<BR><BR><B>Warnings:</B><BR>-You cannot dismantle the machine if the power level is over 0<BR>-You cannot power of the machine if the power level is over 0<BR>-You cannot dispose of waste gases if power level is over 5<BR>-You cannot remove gases from the fusion mix if they are not helium and antinoblium<BR>-Hypernoblium will decrease the power of the mix by a lot<BR>-Antinoblium will INCREASE the power of the mix by a lot more<BR>-High heat capacity gases are harder to heat/cool<BR>-Low heat capacity gases are easier to heat/cool<BR>-The machine consumes 50 KW per power level, reaching 350 KW at power level 6 so prepare the SM accordingly<BR>-In case of a power shortage, the fusion reaction will CONTINUE but the cooling will STOP<BR><BR>The writer of the quick guide will not be held responsible for misuses and meltdown caused by the use of the guide, use more advanced guides to understando how the various gases will act as moderators.";
    }
}

// tg: code/modules/power/turbine/turbine.dm:688
[DmPath("/obj/item/paper/guides/jobs/atmos/turbine"), DmGeneratedOnly]
public partial class obj_item_paper_guides_jobs_atmos_turbine : obj_item_paper_guides_jobs_atmos
{
    // tg: code/modules/power/turbine/turbine.dm:688
    public obj_item_paper_guides_jobs_atmos_turbine()
    {
        name = "paper- 'Quick guide on the new and improved turbine!'";
        default_raw_text = "<B>How to operate the turbine</B><BR>-The new turbine is not much different from the old one, just put gases in the chamber, light them up and activate the machine from the nearby computer.-There is a new parameter that's visible within the turbine computer's UI, damage. The turbine will be damaged when the heat gets too high, according to the tiers of the parts used. Make sure it doesn't get too hot!<BR>-You can avoid the turbine critically failing by upgrading the parts of the machine, but not with stock parts as you might be used to. There are 3 all-new parts, one for each section of the turbine.<BR>-These items are: the compressor part, the rotor part and the stator part. All of them can be printed in any engi lathes (both proto and auto).<BR>-There are 4 tiers for these items, only the first tier can be printed. The next tier of each part can be made by using various materials on the part (clicking with the material in hand, on the part). The material required to reach the next tier is stated in the part's examine text, try shift clicking it!<BR>-Each tier increases the efficiency (more power), the max reachable RPM, and the max temperature that the machine can process without taking damage (up to fusion temperatures at the last tier!).<BR>-A word of warning, the machine is very inefficient in its gas consumption and many unburnt gases will pass through. If you want to be cheap you can either pre-burn the gases or add a filtering system to collect the unburnt gases and reuse them.";
    }
}

