// tg: code/modules/power/solar.dm:641
[DmPath("/obj/item/paper/guides/jobs/engi/solars"), DmGeneratedOnly]
public partial class obj_item_paper_guides_jobs_engi_solars : obj_item_paper_guides_jobs_engi
